import base64, glob, os, shutil, subprocess, sys, zipfile
EMB = {"prepare_yolo_datasets.py": "", "train_shot_model.py": ""}
def sh(cmd):
    print("+", cmd, flush=True)
    subprocess.run(cmd, shell=True, check=True)
sh("nvidia-smi")
sh("pip install -q ultralytics onnx onnxslim")
INP, W, B = "/kaggle/input", "/kaggle/working", "/tmp/padel"
os.makedirs(B, exist_ok=True); os.makedirs(f"{W}/models", exist_ok=True)
z = glob.glob(f"{INP}/**/padel_bundle.zip", recursive=True)
if z:
    zipfile.ZipFile(z[0]).extractall(B)
else:  # Kaggle may have unpacked the zip already
    src = os.path.dirname(os.path.dirname(glob.glob(f"{INP}/**/padelcoach/__init__.py", recursive=True)[0]))
    shutil.copytree(src, B, dirs_exist_ok=True)
os.makedirs(f"{B}/colab_scripts", exist_ok=True)
for name, data in EMB.items():  # latest versions of the scripts
    open(f"{B}/colab_scripts/{name}", "wb").write(base64.b64decode(data))
VID = os.path.dirname(glob.glob(f"{INP}/**/2022_BCN_FinalF_1.mp4", recursive=True)[0])
os.chdir(B)
print("bundle:", os.listdir(B), "videos:", os.listdir(VID), flush=True)
from ultralytics import YOLO

sh(f"python colab_scripts/prepare_yolo_datasets.py --videos {VID} --labels labels --out /tmp/datasets --only ball --ball-step 4")
m = YOLO("yolo11s.pt")
m.train(data="/tmp/datasets/ball.yaml", imgsz=1280, epochs=30, time=9.0, batch=8, patience=8, workers=4,
        mosaic=0.5, degrees=0, scale=0.3, fliplr=0.5, hsv_h=0.01, close_mosaic=5,
        project=f"{W}/runs", name="ball", exist_ok=True)
best = f"{W}/runs/ball/weights/best.pt"
print("BALL mAP50:", YOLO(best).val(data="/tmp/datasets/ball.yaml", imgsz=1280).box.map50, flush=True)
p = YOLO(best).export(format="onnx", imgsz=1280, opset=17, simplify=True)
shutil.copy(p, f"{W}/models/padel_ball.onnx")
print("DONE ball", flush=True)
